public static String getLocalizedString(String key, Locale locale) {
  try {
    ResourceBundle bundle = ResourceBundle.getBundle(resourceBaseName, locale);
    return getLocalizedString(key, locale, null, bundle);
  } catch (com.sun.tools.javac.parser.DocCommentParser.ParseException | java.lang.IllegalArgumentException | java.lang.NullPointerException e) {
    // Log the error and return a default value or a message
    System.err.println("Error retrieving localized string: " + e.getMessage());
    return "Localized string not available";
  }
